// src/app/theme.service.ts
import { Injectable, inject, signal } from '@angular/core';
import { DOCUMENT } from '@angular/common';

export type Theme = 'light' | 'dark';

const STORAGE_KEY = 'uf-theme';
let memoryTheme: Theme = 'light';

function safeReadTheme(): Theme | null {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (raw === 'light' || raw === 'dark') return raw;
  } catch {
    /* sandboxed iframe */
  }
  return null;
}

function safeWriteTheme(theme: Theme): void {
  memoryTheme = theme;
  try {
    window.localStorage.setItem(STORAGE_KEY, theme);
  } catch {
    /* sandboxed iframe */
  }
}

@Injectable({ providedIn: 'root' })
export class ThemeService {
  private readonly document = inject(DOCUMENT);
  private readonly theme = signal<Theme>(safeReadTheme() ?? memoryTheme);
  readonly currentTheme = this.theme.asReadonly();

  constructor() {
    // The root component's inject() creates this service, so <html> has the theme before the first render.
    this.applyTheme(this.theme());
  }

  private applyTheme(theme: Theme): void {
    this.document.documentElement.setAttribute('data-theme', theme);
  }

  setTheme(theme: Theme): void {
    this.theme.set(theme);
    safeWriteTheme(theme);
    this.applyTheme(theme);
  }

  toggleTheme(): void {
    this.setTheme(this.theme() === 'light' ? 'dark' : 'light');
  }
}

// src/app/app.component.ts
import { ChangeDetectionStrategy, Component, computed, inject } from '@angular/core';
import { ThemeService } from './theme.service';

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  private readonly themeService = inject(ThemeService);

  readonly isDark = computed(() => this.themeService.currentTheme() === 'dark');

  onToggleClick(): void {
    this.themeService.toggleTheme();
  }
}
